package com.example.lending.adapter.in.web;

import com.example.lending.domain.BookAlreadyOnLoanException;
import com.example.lending.domain.BookDiscardedException;
import com.example.lending.domain.AlreadyReservedException;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.BookNotOnLoanException;
import com.example.lending.domain.CannotDiscardBookOnLoanException;
import com.example.lending.domain.CreditCheckRejectedException;
import com.example.lending.domain.CreditCheckUnavailableException;
import com.example.lending.domain.LoanAlreadyReturnedException;
import com.example.lending.domain.LoanLimitExceededException;
import com.example.lending.domain.LoanNotFoundException;
import com.example.lending.domain.MemberAlreadyExistsException;
import com.example.lending.domain.MemberNotFoundException;
import com.example.lending.domain.MemberSuspendedException;
import com.example.lending.domain.ReservedForOtherException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
public class WebExceptionHandler {

    @ExceptionHandler(LoanLimitExceededException.class)
    public ResponseEntity<ErrorResponse> handleLoanLimitExceeded(LoanLimitExceededException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse("LOAN_LIMIT_EXCEEDED"));
    }

    @ExceptionHandler(CreditCheckRejectedException.class)
    public ResponseEntity<ErrorResponse> handleCreditRejected(CreditCheckRejectedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse("CREDIT_REJECTED"));
    }

    @ExceptionHandler(CreditCheckUnavailableException.class)
    public ResponseEntity<ErrorResponse> handleCreditCheckUnavailable(CreditCheckUnavailableException e) {
        return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE).body(new ErrorResponse("CREDIT_CHECK_UNAVAILABLE"));
    }

    @ExceptionHandler(MemberAlreadyExistsException.class)
    public ResponseEntity<ErrorResponse> handleMemberAlreadyExists(MemberAlreadyExistsException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse("MEMBER_ALREADY_EXISTS"));
    }

    @ExceptionHandler(MemberSuspendedException.class)
    public ResponseEntity<ErrorResponse> handleMemberSuspended(MemberSuspendedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse("MEMBER_SUSPENDED"));
    }

    @ExceptionHandler(BookDiscardedException.class)
    public ResponseEntity<ErrorResponse> handleBookDiscarded(BookDiscardedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse("BOOK_DISCARDED"));
    }

    @ExceptionHandler(CannotDiscardBookOnLoanException.class)
    public ResponseEntity<ErrorResponse> handleCannotDiscardBookOnLoan(CannotDiscardBookOnLoanException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse("BOOK_ON_LOAN"));
    }

    @ExceptionHandler(BookNotOnLoanException.class)
    public ResponseEntity<ErrorResponse> handleBookNotOnLoan(BookNotOnLoanException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse("BOOK_AVAILABLE"));
    }

    @ExceptionHandler(ReservedForOtherException.class)
    public ResponseEntity<ErrorResponse> handleReservedForOther(ReservedForOtherException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse("RESERVED_FOR_OTHER"));
    }

    @ExceptionHandler(AlreadyReservedException.class)
    public ResponseEntity<ErrorResponse> handleAlreadyReserved(AlreadyReservedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse("ALREADY_RESERVED"));
    }

    @ExceptionHandler(LoanAlreadyReturnedException.class)
    public ResponseEntity<ErrorResponse> handleAlreadyReturned(LoanAlreadyReturnedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse("ALREADY_RETURNED"));
    }

    @ExceptionHandler(LoanNotFoundException.class)
    public ProblemDetail handleLoanNotFound(LoanNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(BookAlreadyOnLoanException.class)
    public ProblemDetail handleAlreadyOnLoan(BookAlreadyOnLoanException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, e.getMessage());
    }

    @ExceptionHandler(BookNotFoundException.class)
    public ProblemDetail handleNotFound(BookNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(MemberNotFoundException.class)
    public ProblemDetail handleMemberNotFound(MemberNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(IllegalArgumentException.class)
    public ProblemDetail handleInvalidInput(IllegalArgumentException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, e.getMessage());
    }
}
package com.example.lending.application.service;

import com.example.lending.application.port.in.ReturnBookUseCase;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.application.port.out.RecordAuditLogPort;
import com.example.lending.application.port.out.SaveBookPort;
import com.example.lending.application.port.out.SaveLoanPort;
import com.example.lending.domain.AuditAction;
import com.example.lending.domain.AuditLog;
import com.example.lending.domain.Book;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.Loan;
import com.example.lending.domain.LoanNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.util.UUID;

@Service
@Transactional
public class ReturnBookService implements ReturnBookUseCase {

    private final LoadLoanPort loadLoanPort;
    private final SaveLoanPort saveLoanPort;
    private final LoadBookPort loadBookPort;
    private final SaveBookPort saveBookPort;
    private final RecordAuditLogPort recordAuditLogPort;

    public ReturnBookService(LoadLoanPort loadLoanPort, SaveLoanPort saveLoanPort,
                             LoadBookPort loadBookPort, SaveBookPort saveBookPort,
                             RecordAuditLogPort recordAuditLogPort) {
        this.loadLoanPort = loadLoanPort;
        this.saveLoanPort = saveLoanPort;
        this.loadBookPort = loadBookPort;
        this.saveBookPort = saveBookPort;
        this.recordAuditLogPort = recordAuditLogPort;
    }

    @Override
    public Loan returnBook(UUID loanId, LocalDate returnedAt) {
        Loan loan = loadLoanPort.loadLoan(loanId)
                .orElseThrow(() -> new LoanNotFoundException(loanId));
        loan.returnOn(returnedAt != null ? returnedAt : LocalDate.now());
        Book book = loadBookPort.loadBook(loan.getBookId())
                .orElseThrow(() -> new BookNotFoundException(loan.getBookId()));
        book.returnFromLoan();
        saveBookPort.saveBook(book);
        saveLoanPort.saveLoan(loan);
        recordAuditLogPort.recordAuditLog(AuditLog.of(AuditAction.RETURN, loan.getId(), loan.getMemberId()));
        return loan;
    }
}
