        loanBookOn(bookId, memberId, "2026-02-02");

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items[0].bookId").value(bookId))
                .andExpect(jsonPath("$.items[0].title").value("Clean Code"))
                .andExpect(jsonPath("$.items[0].loanedAt").value("2026-02-02"))
                .andExpect(jsonPath("$.items[0].dueAt").value("2026-02-16"))
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(20))
                .andExpect(jsonPath("$.totalCount").value(1));
    }

    @Test
    void listing_returns_only_loans_not_yet_returned() throws Exception {
        String memberId = registerMember();
        String returnedLoanId = loanBook(registerBook("Returned Book"), memberId);
        String activeBookId = registerBook("Active Book");
        loanBook(activeBookId, memberId);

        mockMvc.perform(post("/loans/{loanId}/return", returnedLoanId))
