        if (month < 1 || month > 12) {
            throw new IllegalArgumentException("month must be between 1 and 12");
        }
        YearMonth yearMonth = YearMonth.of(year, month);
        LocalDate from = yearMonth.atDay(1);
        LocalDate to = yearMonth.atEndOfMonth();

        long loanCount = loadLoanStatsPort.countLoansLoanedBetween(from, to);
        List<ReturnedLoanView> returnedLoans = loadLoanStatsPort.loadReturnedLoansBetween(from, to);

        long overdueCount = 0;
        long lateFeeTotal = 0;
        for (ReturnedLoanView returnedLoan : returnedLoans) {
            long lateFee = Loan.lateFeeBetween(returnedLoan.dueAt(), returnedLoan.returnedAt());
            if (lateFee > 0) {
                overdueCount++;
                lateFeeTotal += lateFee;
            }
        }
        return new MonthlyStats(year, month, loanCount, returnedLoans.size(), overdueCount, lateFeeTotal);
    }
}

