package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

// 통계 테스트 데이터는 다른 테스트와 DB를 공유하므로 다른 테스트가 쓰지 않는 연도를 사용한다.
@SpringBootTest
@AutoConfigureMockMvc
class MonthlyStatsIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void monthly_stats_count_loans_by_loan_date_and_returns_and_late_fees_by_return_date() throws Exception {
        String memberId = registerMember();
        String otherMemberId = registerMember();

        // 2041-01 대출, 1/10 반납: 연체 없음
        String onTimeLoanId = loanBookOn(registerBook("On Time"), memberId, "2041-01-05");
        // 2041-01 대출, 1/30 반납: 기한 1/24 → 6일 연체 = 600
        String lateLoanId = loanBookOn(registerBook("Late"), memberId, "2041-01-10");
        // 2041-01 대출, 미반납: 대출 건수에만 포함
        loanBookOn(registerBook("Still Out"), memberId, "2041-01-20");
        // 2040-12 대출, 2041-01 반납: 기한 2041-01-03 → 2일 연체 = 200 (반납 달 기준으로 집계)
        String previousYearLoanId = loanBookOn(registerBook("Carried Over"), memberId, "2040-12-20");
        // 2041-01 대출, 2041-02 반납: 대출 건수에만 포함
        String returnedNextMonthId = loanBookOn(registerBook("Next Month"), memberId, "2041-01-15");
        // 2041-01 대출, 1/16 반납 (기한 당일): 연체 아님
        String dueDayLoanId = loanBookOn(registerBook("Due Day"), otherMemberId, "2041-01-02");

        returnLoanOn(onTimeLoanId, "2041-01-10");
        returnLoanOn(lateLoanId, "2041-01-30");
        returnLoanOn(previousYearLoanId, "2041-01-05");
        returnLoanOn(returnedNextMonthId, "2041-02-01");
        returnLoanOn(dueDayLoanId, "2041-01-16");

        mockMvc.perform(get("/stats/monthly").param("year", "2041").param("month", "1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.year").value(2041))
                .andExpect(jsonPath("$.month").value(1))
                .andExpect(jsonPath("$.loanCount").value(5))
                .andExpect(jsonPath("$.returnCount").value(4))
                .andExpect(jsonPath("$.overdueCount").value(2))
                .andExpect(jsonPath("$.lateFeeTotal").value(800));
    }

    @Test
    void monthly_stats_of_a_month_without_activity_are_all_zero() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("year", "2035").param("month", "6"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.year").value(2035))
                .andExpect(jsonPath("$.month").value(6))
                .andExpect(jsonPath("$.loanCount").value(0))
                .andExpect(jsonPath("$.returnCount").value(0))
                .andExpect(jsonPath("$.overdueCount").value(0))
                .andExpect(jsonPath("$.lateFeeTotal").value(0));
    }

    @Test
    void monthly_stats_with_month_out_of_range_returns_400() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("year", "2041").param("month", "13"))
                .andExpect(status().isBadRequest());
    }

    @Test
    void monthly_stats_without_year_or_month_returns_400() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("month", "1"))
                .andExpect(status().isBadRequest());
        mockMvc.perform(get("/stats/monthly").param("year", "2041"))
                .andExpect(status().isBadRequest());
    }

    private void returnLoanOn(String loanId, String returnedAt) throws Exception {
        mockMvc.perform(post("/loans/{loanId}/return", loanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"" + returnedAt + "\"}"))
                .andExpect(status().isOk());
    }

    private String loanBookOn(String bookId, String memberId, String loanedAt) throws Exception {
        String body = "{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId + "\",\"loanedAt\":\"" + loanedAt + "\"}";
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    private String registerMember() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"김민지\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }
}

